pub type Color = { r: Int; g: Int; b: Int; }

impl PartialEq for Color {
  fn eq(self: &Color, other: &Color) -> Bool {
    return self.r == other.r && self.g == other.g && self.b == other.b;
  }
}
impl Eq for Color {}

fn main() -> Int {
  let a = Color{ r: 255, g: 0, b: 0 };
  let b = Color{ r: 255, g: 0, b: 0 };
  if a == b { return 1; }
  return 0;
}
